$formatTechnicalList=static function($value): string {
    $raw=is_array($value)?implode("\n",array_map('strval',$value)):(string)$value;
    // Some historical records contain a title immediately followed by "1. ..." on the same line.
    $raw=preg_replace('/(?<!^)(?=\d{1,3}[.)]\s)/mu',"\n",$raw)??$raw;
    $items=preg_split('/\R|•|\s*;\s*/u',$raw)?:[];
    $items=array_values(array_filter(array_map(static fn($item)=>trim((string)$item),$items),static fn($item)=>$item!==''));
    if(!$items)return '<span style="color:#64748b">Aucune méthodologie renseignée.</span>';

    $html='<table class="methodology-table" width="100%" cellpadding="5" cellspacing="0" border="0">';
    $step=0;
    foreach($items as $index=>$item){
        $next=$items[$index+1]??'';
        $isNumbered=(bool)preg_match('/^\d{1,3}[.)]\s*/u',$item);
        $nextIsNumbered=(bool)preg_match('/^\d{1,3}[.)]\s*/u',$next);
        if(!$isNumbered&&$nextIsNumbered){
            $html.='<tr nobr="true"><td colspan="2" bgcolor="#e8eef8" style="color:#172554;font-weight:bold;font-size:9px;letter-spacing:0.2px;border-top:1px solid #b7c6df;border-bottom:1px solid #b7c6df">'.htmlspecialchars($item,ENT_QUOTES,'UTF-8').'</td></tr>';
            continue;
        }
        $item=preg_replace('/^\d{1,3}[.)]\s*/u','',$item)??$item;
        $step++;
        $html.='<tr nobr="true"><td width="10%" align="center" valign="top" bgcolor="#172554" style="color:#ffffff;font-weight:bold;font-size:8px;border-bottom:2px solid #ffffff">'.str_pad((string)$step,2,'0',STR_PAD_LEFT).'</td><td width="90%" valign="top" bgcolor="#ffffff" style="color:#1e293b;font-size:9px;border-bottom:1px solid #dbe4f0">'.htmlspecialchars($item,ENT_QUOTES,'UTF-8').'</td></tr>';
    }
    return $html.'</table>';
};
