$financeDeadlineLabel=static function(array $deadline): string {
    $type=(string)($deadline['type']??'immediate');
    if($type==='after_delay'){
        $delay=max(1,(int)($deadline['delai']??1));
        $unit=(string)($deadline['unite']??'jour')==='semaine'?'semaine':'jour';
        return 'Paiement '.$delay.' '.($delay>1?$unit.'s':$unit).' après l’exécution de cette phase.';
    }
    if($type==='after_condition'){
        $condition=trim((string)($deadline['condition']??''));
        return $condition!==''?'Paiement sous condition : '.$condition.'.':'Paiement sous condition à préciser.';
    }
    return 'Paiement à l’exécution de cette phase.';
};
