        $financePlanningRows.='<tr bgcolor="#e0e7ff"><td colspan="2"><b>'.$e($group['label']).'</b></td><td align="right"><b>'.number_format($group['total'],0,',',' ').'</b></td><td colspan="3" align="right"><b>Fractions : '.number_format($phaseTotal,2,',',' ').' %</b></td></tr>';
        foreach($financePlanningLabels as $planningIndex=>$planningLabel){
