            $financePlanningRows.='<tr><td>↳ '.$e($planningLabel).$dateLabel.$deadlineLabel.'</td><td align="center">'.number_format($fraction,2,',',' ').' %</td><td align="right">'.number_format($gross,0,',',' ').'</td><td align="right">− '.number_format($recovery,0,',',' ').'</td><td align="right">− '.number_format($retention,0,',',' ').'</td><td align="right"><b>'.number_format($net,0,',',' ').'</b></td></tr>';
            $exportGross+=$gross;$exportRecovery+=$recovery;$exportRetention+=$retention;$exportNet+=$net;$groupNet+=$net;
        }
