    $financeDeadlineDetails='<h2>ÉCHÉANCES DES FRACTIONS DE PAIEMENT</h2><table width="100%" cellpadding="9" cellspacing="0" border="0" style="margin:0 0 12px 0;border:1px solid #dbe4f0;background-color:#f8fafc"><tr><td><span style="font-size:7px;font-weight:bold;color:#b45309;letter-spacing:1px">CONDITIONS DE DÉCAISSEMENT</span><br><span style="font-size:9px;color:#334155">Modalités de règlement présentées par phase du planning, séparément de l’échéancier financier.</span></td></tr></table>';
    foreach($groups as $deadlineGroupId=>$deadlineGroup){$financeDeadlineDetails.='<table width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 9px 0;border:1px solid #cbd5e1" nobr="true"><tr><td bgcolor="#0f172a" style="padding:9px 10px;color:#ffffff"><span style="font-size:7px;color:#fbbf24;font-weight:bold;letter-spacing:1px">DÉBOURSÉ CONCERNÉ</span><br><span style="font-size:10px;font-weight:bold">'.$e($deadlineGroup['label']).'</span></td></tr>';foreach($financePlanningLabels as $deadlineIndex=>$deadlinePlanningLabel){$deadlineKey='planning_'.$deadlineGroupId.'_'.$deadlineIndex;$financeDeadlineDetails.='<tr><td style="padding:8px 10px;border-top:1px solid #e2e8f0"><table width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td width="58%" valign="top"><span style="font-size:7px;color:#64748b;font-weight:bold;letter-spacing:.6px">PHASE DU PLANNING</span><br><span style="font-size:9px;color:#0f172a;font-weight:bold">'.$e($deadlinePlanningLabel).'</span></td><td width="42%" valign="top" style="padding-left:9px;border-left:2px solid #fbbf24"><span style="font-size:7px;color:#64748b;font-weight:bold;letter-spacing:.6px">ÉCHÉANCE</span><br><span style="font-size:8.5px;color:#075985">'.$e($financeDeadlineLabel((array)($financePlanningDeadlines[$deadlineKey]??[]))).'</span></td></tr></table></td></tr>';}$financeDeadlineDetails.='</table>';}
    if($exportRetention>0)$financeDeadlineDetails.='<table width="100%" cellpadding="9" cellspacing="0" border="0" style="margin:0 0 12px 0;border:1px solid #86efac;background-color:#f0fdf4" nobr="true"><tr><td width="58%"><span style="font-size:7px;color:#047857;font-weight:bold;letter-spacing:1px">PAIEMENT FINAL</span><br><span style="font-size:9px;color:#064e3b;font-weight:bold">Restitution de la retenue de garantie</span></td><td width="42%" style="padding-left:9px;border-left:2px solid #34d399"><span style="font-size:7px;color:#047857;font-weight:bold;letter-spacing:1px">ÉCHÉANCE</span><br><span style="font-size:8.5px;color:#065f46">'.$e($financeDeadlineLabel((array)($financePlanningDeadlines['restitution_retenue']??[]))).'</span></td></tr></table>';
    $articleThree='<h2>ARTICLE 3 — ACOMPTE ET PAIEMENTS SUR AVANCEMENT</h2><p>Acompte initial : <b>'.number_format($rate,2,',',' ').' %</b>, soit <b>'.number_format($exportAdvance,0,',',' ').' FCFA</b>. Retenue de garantie : <b>'.number_format($retentionRate,2,',',' ').' %</b>.</p>'.$financeIntro.$financeTable.$financeDeadlineDetails.'<p><i>* Échéancier prévisionnel organisé par déboursé et rubrique du planning.</i></p>';
    $html=preg_replace('~<h2>ARTICLE 3 — ACOMPTE ET PAIEMENTS SUR AVANCEMENT</h2>.*?</table><p><i>\* Échéancier.*?</i></p>~s',$articleThree,$html)??$html;
    if($exportSection==='comptabilite')$html=preg_replace('~<h2>ÉCHÉANCIER FINANCIER</h2>.*?</table>~s','<h2>ÉCHÉANCIER FINANCIER</h2>'.$financeIntro.$financeTable.$financeDeadlineDetails,$html)??$html;
    // Les contrats historiques n’ont pas tous la même structure HTML : dans ce
